import {paths} from './data.js';
export const clone=x=>JSON.parse(JSON.stringify(x));
export function fresh(){return{version:1,onboarded:false,user:{name:'Rani Putri',email:'rani.putri@demo.invalid',education:'Mahasiswa Manajemen',about:'Sedang membangun kemampuan komunikasi dan layanan pelanggan.',skills:['Komunikasi','Excel','Presentasi','Analisis data'],interests:['Keuangan','Layanan pelanggan'],experience:'Staf Divisi Keuangan · Organisasi Kampus (2022–2023)'},cv:null,path:'banking',completed:[],ledger:{},caseResults:{},saved:[],applications:[],notifications:[],activity:[],connections:[],liked:[],posts:[],messages:[],notificationEnabled:true};}
export function recommend(user){return paths.map(p=>{const hits=p.skills.filter(s=>user.skills.map(x=>x.toLowerCase()).includes(s.toLowerCase())).length,interests=p.interests.filter(x=>user.interests.includes(x)).length;return{...p,score:Math.round(Math.min(96,40+30*hits/p.skills.length+20*interests)),hits}}).sort((a,b)=>b.score-a.score);}
export function xp(s){return Object.values(s.ledger).reduce((sum,n)=>sum+n,0)}
export function award(s,key,amount){if(Object.hasOwn(s.ledger,key))return false;s.ledger[key]=amount;return true}
export function dayKey(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-')}
export function recordActivity(s,date=new Date()){const day=dayKey(date);if(!s.activity.includes(day))s.activity.push(day)}
export function streak(s,date=new Date()){const d=new Date(date.getFullYear(),date.getMonth(),date.getDate());if(!s.activity.includes(dayKey(d)))d.setDate(d.getDate()-1);let count=0;while(s.activity.includes(dayKey(d))){count++;d.setDate(d.getDate()-1)}return count}
export function profileCompletion(s){return Math.round([s.user.name.trim(),s.user.email.trim(),s.user.education.trim(),s.user.experience.trim(),s.user.skills.length,s.cv].filter(Boolean).length/6*100)}
export function readiness(s){const modules=s.completed.filter(id=>id.startsWith(s.path+':')).length,caseScore=s.caseResults[s.path]?.score||0;return Math.round(profileCompletion(s)*.2+modules/8*50+caseScore*.3)}
export function completeModule(s,path,index,score){if(score<60)return false;const id=path+':'+index;if(!s.completed.includes(id))s.completed.push(id);const first=award(s,'module:'+id,150);recordActivity(s);return first}
export function completeCase(s,path,answers){const score=Math.round(answers.reduce((n,a)=>n+a,0)/(answers.length*2)*100),old=s.caseResults[path];if(!old||score>old.score)s.caseResults[path]={score,completedAt:new Date().toISOString()};const first=score>=60&&award(s,'case:'+path,200);recordActivity(s);return{score,first}}
export function addNotice(s,title,text,type='sistem',target='home',data={}){const notice={id:'n'+Date.now()+Math.random().toString(36).slice(2,6),title,text,type,target,data,read:false,at:new Date().toISOString()};s.notifications.unshift(notice);return notice}
export function applyJob(s,job,motivation,consent){if(!s.cv)return{error:'Lampirkan CV atau gunakan CV contoh terlebih dahulu.'};if(!consent)return{error:'Konfirmasi data diperlukan untuk membuat lamaran simulasi.'};if(motivation.length>500)return{error:'Surat motivasi maksimal 500 karakter.'};if(s.applications.some(a=>a.job===job.id))return{error:'Lamaran simulasi untuk posisi ini sudah ada.'};const a={id:'a'+Date.now(),job:job.id,status:0,history:[{status:0,at:new Date().toISOString()}],motivation,cvName:s.cv.name,createdAt:new Date().toISOString()};s.applications.push(a);addNotice(s,'Lamaran simulasi dibuat',job.title+' tersimpan di pelacakan. Tidak dikirim ke perusahaan.','lamaran','application',{id:a.id});return{application:a}}
export const statuses=['Dibuat','Ditinjau','Wawancara','Hasil akhir'];
export function advanceApplication(s,id,outcome='diterima'){const a=s.applications.find(a=>a.id===id);if(!a||a.status>=3)return false;a.status++;if(a.status===3)a.outcome=outcome;a.history.push({status:a.status,at:new Date().toISOString()});addNotice(s,'Status demo diperbarui',statuses[a.status]+(a.status===3?' · '+outcome:'')+'. Perubahan ini dipicu simulator.','lamaran','application',{id});return true}
